"""Tests for GET /reports?customer=<name> (written before reports.py, per the security skill's Unit-test focus)."""
import hashlib
import hmac
import os
import sqlite3
import tempfile
import unittest
from unittest import mock

import reports

FAKE_KEY = "test-only-fake-signing-key"  # a fake; the real key lives only in the environment / secret store


def token_for(caller, key=FAKE_KEY):
    sig = hmac.new(key.encode(), caller.encode(), hashlib.sha256).hexdigest()
    return "Bearer %s.%s" % (caller, sig)


class Base(unittest.TestCase):
    def setUp(self):
        fd, self.db = tempfile.mkstemp(suffix=".db")
        os.close(fd)
        con = sqlite3.connect(self.db)
        con.execute("CREATE TABLE reports (customer TEXT, title TEXT)")
        con.executemany("INSERT INTO reports VALUES (?, ?)",
                        [("acme", "Q1"), ("acme", "Q2"), ("globex", "secret-Q1")])
        con.commit()
        con.close()
        env = {"REPORTS_SIGNING_KEY": FAKE_KEY, "REPORTS_DB_PATH": self.db}
        self.env = mock.patch.dict(os.environ, env, clear=False)
        self.env.start()
        # caller -> customers it may read
        self.acl = {"alice": {"acme"}}

    def tearDown(self):
        self.env.stop()
        os.remove(self.db)

    def get(self, query, auth=None):
        return reports.handle_get_reports(query, {"Authorization": auth} if auth else {}, self.acl)


class AllowedCaller(Base):
    def test_returns_only_that_customers_reports(self):
        status, body = self.get({"customer": "acme"}, token_for("alice"))
        self.assertEqual(status, 200)
        self.assertEqual(body, {"customer": "acme", "reports": ["Q1", "Q2"]})


class HostileInput(Base):
    def assertRejected(self, value):
        status, body = self.get({"customer": value}, token_for("alice"))
        self.assertEqual(status, 400)
        self.assertNotIn(str(value), str(body))  # input is not echoed back

    def test_quote_injection(self):
        self.assertRejected("acme' OR '1'='1")

    def test_separator(self):
        self.assertRejected("acme; DROP TABLE reports;--")

    def test_path_traversal(self):
        self.assertRejected("../etc/passwd")

    def test_oversized(self):
        self.assertRejected("a" * 65)

    def test_empty(self):
        self.assertRejected("")

    def test_missing(self):
        status, _ = self.get({}, token_for("alice"))
        self.assertEqual(status, 400)

    def test_wrong_type(self):
        status, _ = self.get({"customer": ["acme", "globex"]}, token_for("alice"))
        self.assertEqual(status, 400)

    def test_table_survives_injection_attempt(self):
        self.get({"customer": "x'; DROP TABLE reports;--"}, token_for("alice"))
        con = sqlite3.connect(self.db)
        self.assertEqual(con.execute("SELECT COUNT(*) FROM reports").fetchone()[0], 3)
        con.close()


class DeniedCaller(Base):
    def test_no_credential(self):
        self.assertEqual(self.get({"customer": "acme"})[0], 401)

    def test_wrong_credential(self):
        self.assertEqual(self.get({"customer": "acme"}, token_for("alice", key="wrong"))[0], 401)

    def test_malformed_credential(self):
        self.assertEqual(self.get({"customer": "acme"}, "Bearer garbage")[0], 401)

    def test_too_little_access(self):
        status, body = self.get({"customer": "globex"}, token_for("alice"))
        self.assertEqual(status, 403)
        self.assertNotIn("secret-Q1", str(body))

    def test_unknown_caller_with_valid_signature_is_denied(self):
        self.assertEqual(self.get({"customer": "acme"}, token_for("mallory"))[0], 403)


class FailClosed(Base):
    def test_missing_signing_key(self):
        with mock.patch.dict(os.environ, {}, clear=True):
            status, body = self.get({"customer": "acme"}, token_for("alice"))
        self.assertEqual(status, 500)
        self.assertNotIn("REPORTS_SIGNING_KEY", str(body))
        self.assertNotIn(FAKE_KEY, str(body))

    def test_connection_is_read_only(self):
        con = reports.connect_read_only()
        with self.assertRaises(sqlite3.OperationalError):
            con.execute("DELETE FROM reports")
        con.close()

    def test_no_secret_or_personal_value_in_logs(self):
        with self.assertLogs("reports", level="INFO") as logs:
            self.get({"customer": "globex"}, token_for("alice"))
            self.get({"customer": "x' OR 1=1"}, token_for("alice", key="wrong"))
        joined = "\n".join(logs.output)
        for leaked in (FAKE_KEY, token_for("alice"), "globex", "OR 1=1"):
            self.assertNotIn(leaked, joined)


if __name__ == "__main__":
    unittest.main()
